package java.util.concurrent;
import java.util.*;
public class ConcurrentSkipListMap<K,V> extends TreeMap<K,V> implements ConcurrentMap<K,V>,Cloneable,java.io.Serializable {
 public ConcurrentSkipListMap(){super();}public ConcurrentSkipListMap(Comparator<? super K> c){super(c);}public ConcurrentSkipListMap(Map<? extends K,? extends V> m){super();putAll(m);}public V put(K k,V v){if(k==null||v==null)throw new NullPointerException();return super.put(k,v);}public V putIfAbsent(K k,V v){if(v==null)throw new NullPointerException();V old=get(k);if(old==null)put(k,v);return old;}public boolean remove(Object k,Object v){if(k==null||v==null)throw new NullPointerException();V old=get(k);if(!v.equals(old))return false;remove(k);return true;}public boolean replace(K k,V old,V v){if(old==null||v==null)throw new NullPointerException();if(!old.equals(get(k)))return false;put(k,v);return true;}public V replace(K k,V v){if(v==null)throw new NullPointerException();V old=get(k);if(old!=null)put(k,v);return old;}
 private int compare(K a,K b){Comparator<? super K> c=comparator();return c==null?((Comparable<? super K>)a).compareTo(b):c.compare(a,b);}private K near(K k,int mode){if(k==null)throw new NullPointerException();K found=null;for(K x:keySet()){int c=compare(x,k);if(c<0||(c==0&&(mode==1||mode==2))){if(mode<2)found=x;else if(c==0)return x;}else if(mode>=2&&(c>0||(c==0&&mode==2)))return x;}return found;}public K lowerKey(K k){return near(k,0);}public K floorKey(K k){return near(k,1);}public K ceilingKey(K k){return near(k,2);}public K higherKey(K k){return near(k,3);}
 public Map.Entry<K,V> firstEntry(){return isEmpty()?null:new AbstractMap.SimpleImmutableEntry<K,V>(firstKey(),get(firstKey()));}public Map.Entry<K,V> lastEntry(){return isEmpty()?null:new AbstractMap.SimpleImmutableEntry<K,V>(lastKey(),get(lastKey()));}public Map.Entry<K,V> pollFirstEntry(){Map.Entry<K,V> e=firstEntry();if(e!=null)remove(e.getKey());return e;}public Map.Entry<K,V> pollLastEntry(){Map.Entry<K,V> e=lastEntry();if(e!=null)remove(e.getKey());return e;}
}
